def compute(vars):
    high = vars["v1"]
    low = vars["v2"]
    difference = high - low
    return {
        "value": difference,
        "trace": {
            "high_sale_price": high,
            "low_sale_price": low,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "currency/share"
            }
        }
    }
